"use client"

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion"
import { Container } from "@/components/ui/container"
import { Wrapper } from "@/components/ui/wrapper"
import { FadeIn } from "@/components/ui/fade-in"
import { SectionBadge } from "@/components/ui/section-badge"

const faqs = [
  {
    question: "Do I own the code and IP?",
    answer: "Yes. Unlike other agencies that license their platform to you, we build custom software that you own 100%. We hand over all source code, documentation, and IP rights upon completion."
  },
  {
    question: "How long does it take to build an AI Agent?",
    answer: "It depends on complexity. Simple automation agents can be deployed in 2-3 weeks. Complex enterprise architectures typically take 6-10 weeks from discovery to production launch."
  },
  {
    question: "Is my data secure?",
    answer: "Security is our priority. We implement enterprise-grade guardrails, PII redaction, and can deploy on your private cloud infrastructure (AWS/GCP/Azure) so your data never leaves your control."
  },
  {
    question: "Do you provide ongoing support?",
    answer: "Yes. We offer optional maintenance packages to monitor agent performance, handle model updates, and keep your workflows running smoothly. You can also choose to have your internal team manage it."
  },
  {
    question: "How is this different from ChatGPT?",
    answer: "ChatGPT is a general chat interface. Arbor builds workflow agents and connected automations that follow defined business rules, draft updates, trigger approved actions, and hand off exceptions for human review."
  }
]

export function FAQ() {
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": faqs.map((faq) => ({
      "@type": "Question",
      "name": faq.question,
      "acceptedAnswer": {
        "@type": "Answer",
        "text": faq.answer
      }
    }))
  };

  return (
    <Wrapper className="relative z-10 pb-14 pt-0 md:pb-20">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <Container>
        <div className="mx-auto grid max-w-6xl grid-cols-1 items-stretch gap-6 lg:grid-cols-[minmax(280px,0.8fr)_minmax(0,1.7fr)]">
          <FadeIn className="h-full">
            <div className="flex h-full flex-col justify-center rounded-xl border border-primary/15 bg-primary/[0.06] p-6 shadow-sm backdrop-blur-sm md:rounded-2xl md:p-8">
              <SectionBadge title="FAQ" className="mb-4 md:mb-6" />
              <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold mb-4 md:mb-6">
                Common Questions
              </h2>
              <p className="max-w-sm text-base leading-relaxed text-muted-foreground md:text-lg">
                Everything you need to know about our process and how we work.
              </p>
            </div>
          </FadeIn>

          <div>
            <FadeIn className="h-full" delay={0.2}>
              <div className="h-full rounded-xl border border-border/60 bg-card/70 p-4 shadow-sm backdrop-blur-md md:rounded-2xl md:px-8 md:py-5">
                <Accordion type="single" collapsible className="w-full">
                  {faqs.map((faq, i) => (
                    <AccordionItem key={i} value={`item-${i}`} className="border-b-border/50 last:border-0">
                      <AccordionTrigger className="text-left text-base md:text-lg font-medium hover:text-primary transition-colors">
                        {faq.question}
                      </AccordionTrigger>
                      <AccordionContent className="text-muted-foreground text-base leading-relaxed">
                        {faq.answer}
                      </AccordionContent>
                    </AccordionItem>
                  ))}
                </Accordion>
              </div>
            </FadeIn>
          </div>
        </div>
      </Container>
    </Wrapper>
  )
}
