import {
  AI_READINESS_PILLARS,
  type AiReadinessPillar,
  type PillarResult,
} from "@/lib/ai-readiness"

type ReadinessRadarProps = {
  results: PillarResult[]
}

const CENTER = 180
const RADIUS = 112
const LABEL_RADIUS = 148
function polarPoint(index: number, radius: number) {
  const angle = -Math.PI / 2 + (index * Math.PI * 2) / AI_READINESS_PILLARS.length

  return {
    x: CENTER + Math.cos(angle) * radius,
    y: CENTER + Math.sin(angle) * radius,
  }
}

function pointsForRadius(radius: number) {
  return AI_READINESS_PILLARS.map((_, index) => {
    const point = polarPoint(index, radius)
    return `${point.x},${point.y}`
  }).join(" ")
}

export function ReadinessRadar({ results }: ReadinessRadarProps) {
  const byPillar = Object.fromEntries(
    results.map((result) => [result.pillar, result.score]),
  ) as Record<AiReadinessPillar, number>

  const resultPoints = AI_READINESS_PILLARS.map((pillar, index) => {
    const scoreRadius = RADIUS * (byPillar[pillar] / 100)
    const point = polarPoint(index, scoreRadius)
    return `${point.x},${point.y}`
  }).join(" ")

  return (
    <figure>
      <svg
        aria-labelledby="readiness-radar-title readiness-radar-description"
        className="mx-auto h-auto w-full max-w-[430px] overflow-visible"
        role="img"
        viewBox="0 0 360 360"
      >
        <title id="readiness-radar-title">AI readiness capability radar</title>
        <desc id="readiness-radar-description">
          A five-axis chart comparing Strategy, Data, Technology, Talent, and Governance scores.
        </desc>

        {[0.25, 0.5, 0.75, 1].map((level) => (
          <polygon
            key={level}
            className="fill-none stroke-border"
            points={pointsForRadius(RADIUS * level)}
            strokeDasharray={level === 1 ? "5 6" : "3 7"}
            strokeWidth={level === 1 ? 1.5 : 1}
            vectorEffect="non-scaling-stroke"
          />
        ))}

        {AI_READINESS_PILLARS.map((pillar, index) => {
          const endpoint = polarPoint(index, RADIUS)
          return (
            <line
              key={pillar}
              className="stroke-border"
              x1={CENTER}
              x2={endpoint.x}
              y1={CENTER}
              y2={endpoint.y}
              vectorEffect="non-scaling-stroke"
            />
          )
        })}

        <polygon
          className="fill-primary/20 stroke-primary"
          points={resultPoints}
          strokeLinejoin="round"
          strokeWidth="3"
          vectorEffect="non-scaling-stroke"
        />

        {AI_READINESS_PILLARS.map((pillar, index) => {
          const scoreRadius = RADIUS * (byPillar[pillar] / 100)
          const point = polarPoint(index, scoreRadius)
          return (
            <circle
              key={pillar}
              className="fill-primary stroke-card"
              cx={point.x}
              cy={point.y}
              r="5"
              strokeWidth="2"
              vectorEffect="non-scaling-stroke"
            />
          )
        })}

        {AI_READINESS_PILLARS.map((pillar, index) => {
          const point = polarPoint(index, LABEL_RADIUS)
          const isLeft = point.x < CENTER - 16
          const isRight = point.x > CENTER + 16
          const labelX = isLeft ? 4 : isRight ? 356 : point.x
          const textAnchor = isLeft ? "start" : isRight ? "end" : "middle"

          return (
            <g key={pillar}>
              <text
                className="fill-foreground text-[12px] font-semibold"
                dominantBaseline="middle"
                textAnchor={textAnchor}
                x={labelX}
                y={point.y}
              >
                {pillar}
              </text>
              <text
                className="fill-primary text-[11px] font-bold"
                dominantBaseline="hanging"
                textAnchor={textAnchor}
                x={labelX}
                y={point.y + 10}
              >
                {byPillar[pillar]}%
              </text>
            </g>
          )
        })}
      </svg>
    </figure>
  )
}
